<?php defined('BASEPATH') or exit('No direct script access allowed');

function search_meta_exists($search_id, $meta_key) {
	$CI = &get_instance();
	$sql = "SELECT search_ID, meta_key FROM " . db_prefix() . "search_meta WHERE meta_key = ? AND search_ID = ?";
	$query = $CI->db->query($sql, array( $meta_key, $search_id ));
	
	if ( $query->num_rows() > 0 ) {
		return true;
	}

	return;
}

function add_search_meta($search_id, $meta_key, $meta_value) {
	$CI = &get_instance();
	$value = $meta_value;
	if ( is_array($meta_value) || is_object($meta_value) ) {
		$value = serialize($meta_value);
	}

	$data = array(
		'search_ID' => $search_id,
		'meta_key' => $meta_key,
		'meta_value' => $value
	);

	if ( ! search_meta_exists($search_id, $meta_key) ) {
		$CI->db->insert( db_prefix() . 'search_meta', $data );
	}
}

function update_search_meta($search_id, $meta_key, $meta_value) {
	$CI = &get_instance();
	$value = $meta_value;
	if ( is_array($meta_value) || is_object($meta_value) ) {
		$value = serialize($meta_value);
	}

	$data = array(
		'meta_key' => $meta_key,
		'meta_value' => $value
	);

	if ( search_meta_exists($search_id, $meta_key) ) {
		$CI->db->where('search_ID', $search_id);
		$CI->db->where('meta_key', $meta_key);
		$CI->db->update( db_prefix() . 'search_meta', $data );
	} else {
		$data['search_ID'] = $search_id;
		$CI->db->insert( db_prefix() . 'search_meta', $data );
	}
}

function get_search_meta($search_id, $meta_key = '') {
	$CI = &get_instance();
	$CI->db->where('search_ID', $search_id);
	$CI->db->where('meta_key', $meta_key);
	$meta = $CI->db->get(db_prefix().'search_meta');
	if ( $meta->num_rows() > 0 ) {
		$result = $meta->row();
		$value = $result->meta_value;
		$data = @unserialize($value);
		if ( $data !== false ) {
			return unserialize($value);
		} else {
			return $value;
		}
	}

	return;
}

function delete_search_meta($search_id, $meta_key) {
	if ( search_meta_exists($search_id, $meta_key) ) {
		$CI->db->delete( db_prefix() . 'search_meta', array( 'search_ID' => $search_id, 'meta_key' => $meta_key ) ); 
	}
}

